import csv
import io
import unittest
from exporter import export_rows

def _rows(rows):
    return list(csv.reader(io.StringIO(export_rows(rows))))[1:]

class ExportTests(unittest.TestCase):
    def test_header(self):
        self.assertTrue(export_rows([]).startswith("customer_id,region"))

    def test_absent_region_is_na(self):
        self.assertEqual(_rows([{"customer_id": "1"}]), [["1", "NA"]])

    def test_none_region_is_na(self):
        self.assertEqual(_rows([{"customer_id": "1", "region": None}]), [["1", "NA"]])

    def test_empty_region_is_preserved(self):
        self.assertEqual(_rows([{"customer_id": "1", "region": ""}]), [["1", ""]])

    def test_non_empty_region_is_preserved(self):
        self.assertEqual(_rows([{"customer_id": "1", "region": "EU"}]), [["1", "EU"]])

    def test_customer_id_preserved_with_leading_zeros(self):
        self.assertEqual(_rows([{"customer_id": "007", "region": None}]), [["007", "NA"]])

if __name__ == "__main__":
    unittest.main()

